def reference(vectors):
    out = []
    state = 0
    prev = None
    for v in vectors:
        reset = v.get('reset', 0)
        inp = v.get('in', 0) & 0xFFFFFFFF
        if reset:
            state = 0
        else:
            if prev is not None:
                state |= (prev & ~inp) & 0xFFFFFFFF
            state &= 0xFFFFFFFF
        prev = inp
